 bool modeKeepPage;DispatcherTimer modeTimer;ModeLaunchSession modeSession;string modeMessage="";
 void ModesPage(StackPanel root){var tools=new WrapPanel{Margin=new Thickness(0,0,0,16)};var create=Btn("+  Nouveau mode",delegate{EditMode(null);},true);create.IsEnabled=modeSession==null;tools.Children.Add(create);RoutineExamples(tools);if(modeSession!=null)tools.Children.Add(Btn("Arrêter les ouvertures",delegate{CancelModeLaunch();modeMessage="Ouvertures arrêtées. Les applications déjà lancées restent ouvertes.";Refresh();}));root.Children.Add(tools);root.Children.Add(T("Un clic pour ouvrir vos applications, dossiers et sites, puis retrouver une note ou un projet. Chaque mode se configure sur votre PC.",12,Muted,new Thickness(0,0,0,16)));if(!String.IsNullOrEmpty(modeMessage))root.Children.Add(T(modeMessage,12,Accent,new Thickness(0,0,0,16)));if(store.Value.modes.Count==0){var starter=new StackPanel();starter.Children.Add(T("Partez d’un exemple et choisissez ce qu’il doit ouvrir.",13,Muted,new Thickness(0,0,0,15)));var choices=new WrapPanel();foreach(string preset in new[]{"Travail","Stream","Perso"}){string name=preset;choices.Children.Add(Btn(name,delegate{var mode=new LaunchMode{name=name,description=name=="Travail"?"Mes outils et mes dossiers de travail":name=="Stream"?"Préparer ma session de stream":"Mon espace personnel"};if(name=="Stream"){mode.actions.Add(new ModeAction{kind="discord",label="Discord"});mode.actions.Add(new ModeAction{kind="spotify",label="Spotify"});}EditMode(mode);}));}starter.Children.Add(choices);root.Children.Add(Card("Votre premier mode",starter));}foreach(var item in store.Value.modes){var mode=item;var body=new StackPanel();if(!String.IsNullOrWhiteSpace(mode.description))body.Children.Add(T(mode.description,13,Muted,new Thickness(0,0,0,12)));foreach(var action in mode.actions){body.Children.Add(T(LaunchModes.KindName(action.kind)+" · "+action.label,12,Ink,new Thickness(0,4,0,2)));if(!String.IsNullOrEmpty(action.target)){var path=T(action.target,10,Muted,new Thickness(0,0,0,6));path.TextWrapping=TextWrapping.Wrap;body.Children.Add(path);}}if(!String.IsNullOrEmpty(mode.pageKind))body.Children.Add(T("Puis ouvrir · "+DestinationTitle(mode),12,Accent,new Thickness(0,10,0,10)));var buttons=new WrapPanel{Margin=new Thickness(0,12,0,0)};var run=Btn("▶  Lancer",delegate{RunMode(mode);},true);run.IsEnabled=modeSession==null;buttons.Children.Add(run);var edit=Btn("Modifier",delegate{EditMode(mode);},false,true);edit.IsEnabled=modeSession==null;buttons.Children.Add(edit);buttons.Children.Add(FavoriteButton("mode",mode.id,mode.name));body.Children.Add(buttons);var card=Card(mode.name,body);card.Margin=new Thickness(0,0,0,16);root.Children.Add(card);}}
 string DestinationTitle(LaunchMode mode){if(mode.pageKind=="note"){var n=store.Value.pages.FirstOrDefault(candidate=>candidate.id==mode.pageId&&!candidate.trashed);return n==null?"Note indisponible":n.title;}return mode.pageId;}
 void EditMode(LaunchMode existing){if(modeSession!=null)return;var draft=existing==null?new LaunchMode():LaunchModes.Clone(existing);bool editing=existing!=null&&store.Value.modes.Contains(existing);StackPanel body,actions;var w=Dialog(editing?"Modifier le mode":"Nouveau mode",out body,out actions,800);var name=new TextBox{Text=draft.name,MaxLength=60};Field(body,"Nom du mode",name);var description=new TextBox{Text=draft.description,MaxLength=500,Height=70,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap};Field(body,"Description (facultatif)",description);body.Children.Add(T("À ouvrir, dans cet ordre",12,Muted,new Thickness(0,0,0,8)));var list=new StackPanel();body.Children.Add(list);Action draw=null;draw=delegate{list.Children.Clear();for(int i=0;i<draft.actions.Count;i++){int index=i;var action=draft.actions[i];var row=new DockPanel();var controls=new StackPanel{Orientation=Orientation.Horizontal};controls.Children.Add(Btn("↑",delegate{if(index>0){draft.actions.RemoveAt(index);draft.actions.Insert(index-1,action);draw();}},false,true));controls.Children.Add(Btn("↓",delegate{if(index<draft.actions.Count-1){draft.actions.RemoveAt(index);draft.actions.Insert(index+1,action);draw();}},false,true));controls.Children.Add(Btn("×",delegate{draft.actions.RemoveAt(index);draw();},false,true));DockPanel.SetDock(controls,Dock.Right);row.Children.Add(controls);var labels=new StackPanel();labels.Children.Add(T(action.label,12));labels.Children.Add(T(String.IsNullOrEmpty(action.target)?LaunchModes.KindName(action.kind):action.target,10,Muted));row.Children.Add(labels);var box=Box(row,new Thickness(10));box.Margin=new Thickness(0,0,0,8);list.Children.Add(box);}if(draft.actions.Count==0)list.Children.Add(T("Ajoutez des ouvertures, ou choisissez simplement un accueil ci-dessous.",12,Muted,new Thickness(0,4,0,12)));};draw();Action<ModeAction> add=delegate(ModeAction action){if(draft.actions.Count>=20){MessageBox.Show("Un mode peut ouvrir jusqu’à 20 éléments.");return;}draft.actions.Add(action);draw();};var addButtons=new WrapPanel{Margin=new Thickness(0,8,0,18)};addButtons.Children.Add(Btn("+  Application",delegate{using(var picker=new System.Windows.Forms.OpenFileDialog{Title="Choisir une application",Filter="Application Windows|*.exe"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK)add(new ModeAction{kind="exe",label=Path.GetFileNameWithoutExtension(picker.FileName),target=picker.FileName});},false,true));addButtons.Children.Add(Btn("+  Dossier",delegate{using(var picker=new System.Windows.Forms.FolderBrowserDialog{Description="Choisir un dossier à ouvrir",ShowNewFolderButton=false})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK){string path=picker.SelectedPath,label=Path.GetFileName(picker.SelectedPath.TrimEnd(Path.DirectorySeparatorChar));add(new ModeAction{kind="folder",label=String.IsNullOrEmpty(label)?path:label,target=path});}},false,true));addButtons.Children.Add(Btn("+  Site web",delegate{var link=ModeLink();if(link!=null)add(link);},false,true));addButtons.Children.Add(Btn("+  Discord",delegate{add(new ModeAction{kind="discord",label="Discord"});},false,true));addButtons.Children.Add(Btn("+  Spotify",delegate{add(new ModeAction{kind="spotify",label="Spotify"});},false,true));body.Children.Add(addButtons);var destinations=new List<ModeDestination>{new ModeDestination{Kind="",Id="",Label="Rester sur la page actuelle"}};destinations.AddRange(owner.AllProjects().Select(p=>new ModeDestination{Kind="project",Id=p,Label="Projet · "+p}));destinations.AddRange(store.Value.pages.Where(n=>!n.trashed).OrderBy(n=>n.title).Select(n=>new ModeDestination{Kind="note",Id=n.id,Label="Note · "+n.title}));var selectedDestination=destinations.FirstOrDefault(d=>d.Kind==draft.pageKind&&d.Id==draft.pageId);if(selectedDestination==null){selectedDestination=new ModeDestination{Kind=draft.pageKind,Id=draft.pageId,Label="Destination indisponible · "+draft.pageId};destinations.Add(selectedDestination);}var destination=new ComboBox{ItemsSource=destinations,DisplayMemberPath="Label",SelectedItem=selectedDestination};Field(body,"Page à retrouver à la fin",destination);var saveRoutine=SaveRoutineFields(body,draft);var saveDofus=DofusModeFields(body,draft);body.Children.Add(T("Discord et Spotify ouvrent les applications installées. Les sites utilisent votre navigateur par défaut. Le mode ne ferme aucune application et ne démarre pas un live.",11,Muted,new Thickness(0,0,0,12)));var error=T("",12,Accent);body.Children.Add(error);if(editing)actions.Children.Add(Btn("Supprimer",delegate{if(System.Windows.Forms.MessageBox.Show("Supprimer ce mode ? Ses applications, dossiers et contenus sont conservés.","Mon espace",System.Windows.Forms.MessageBoxButtons.YesNo)==System.Windows.Forms.DialogResult.Yes){store.Value.modes.Remove(existing);owner.Save();w.DialogResult=false;}},false,true));actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Enregistrer",delegate{var page=(ModeDestination)destination.SelectedItem;draft.name=name.Text.Trim();draft.description=description.Text.Trim();draft.pageKind=page.Kind;draft.pageId=page.Id;saveRoutine();saveDofus();if(String.IsNullOrWhiteSpace(draft.name)||(draft.actions.Count==0&&String.IsNullOrEmpty(draft.pageKind)&&String.IsNullOrEmpty(draft.homePreset)&&(draft.dofusView=="off"||draft.dofusView=="auto"))){error.Text="Indiquez un nom et au moins une ouverture, une page ou un accueil.";error.BringIntoView();return;}if(!editing)draft.id=Guid.NewGuid().ToString();int index=editing?store.Value.modes.IndexOf(existing):-1;if(editing)store.Value.modes[index]=draft;else store.Value.modes.Add(draft);if(!owner.Save()){if(editing)store.Value.modes[index]=existing;else store.Value.modes.Remove(draft);return;}w.DialogResult=true;},true));ShowWindow(w);Refresh();}
 ModeAction ModeLink(){StackPanel body,actions;var w=Dialog("Site du mode",out body,out actions,430);var name=new TextBox{MaxLength=200};var url=new TextBox{Text="https://",MaxLength=2048};Field(body,"Nom",name);Field(body,"Adresse",url);var error=T("",12,Accent);body.Children.Add(error);ModeAction result=null;actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Ajouter",delegate{var action=new ModeAction{kind="url",label=name.Text.Trim(),target=url.Text.Trim()};try{LaunchModes.ValidateAction(action);}catch(Exception ex){error.Text=ex.Message;return;}result=action;w.DialogResult=true;},true));return ShowWindow(w)==true?result:null;}
 void RunMode(LaunchMode mode,bool keepPage=false){if(modeSession!=null){MessageBox.Show("Un mode est déjà en cours d’ouverture.");return;}if(!String.IsNullOrEmpty(mode.homePreset)&&!ActivateModeHome(mode))return;modeKeepPage=keepPage;modeSession=new ModeLaunchSession(mode);modeMessage="Ouverture du mode « "+mode.name+" »…";modeTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(450)};modeTimer.Tick+=delegate{if(modeSession==null)return;if(modeSession.Step(LaunchModes.Execute))FinishMode();};modeTimer.Start();Refresh();}
 void FinishMode(){modeTimer.Stop();modeTimer=null;var session=modeSession;modeSession=null;modeMessage=session.Mode.name+" · "+session.Opened+" ouverture(s) lancée(s)"+(session.Errors.Count>0?" · "+session.Errors.Count+" échec(s)":"");if(!modeKeepPage&&session.Mode.pageKind=="project"){if(owner.AllProjects().Contains(session.Mode.pageId))OpenProject(session.Mode.pageId);else session.Errors.Add("Projet de destination indisponible.");}else if(!modeKeepPage&&session.Mode.pageKind=="note"){var note=store.Value.pages.FirstOrDefault(n=>n.id==session.Mode.pageId&&!n.trashed);if(note!=null)ReadNote(note);else session.Errors.Add("Note de destination indisponible.");}if(!modeKeepPage&&String.IsNullOrEmpty(session.Mode.pageKind)&&!String.IsNullOrEmpty(session.Mode.homePreset))Go("Aujourd’hui");FinishDofusMode(session.Mode,modeKeepPage);Refresh();if(session.Errors.Count>0)MessageBox.Show("Le mode a terminé ses ouvertures. Éléments indisponibles :\n\n"+String.Join("\n",session.Errors),"Mode « "+session.Mode.name+" »");}
 internal void CancelModeLaunch(){if(modeSession!=null)modeSession.Cancelled=true;if(modeTimer!=null)modeTimer.Stop();modeTimer=null;modeSession=null;}
 StackPanel ModeButtons(bool compact){var body=new StackPanel();foreach(var mode in store.Value.modes.Take(compact?2:4)){var item=mode;var b=Btn("▶  "+mode.name,delegate{RunMode(item);},false,true);b.HorizontalContentAlignment=HorizontalAlignment.Left;b.IsEnabled=modeSession==null;body.Children.Add(b);}if(store.Value.modes.Count==0)body.Children.Add(Btn("Créer mon premier mode",delegate{Go("Mes modes");},false,true));return body;}
 internal void PreviewModes(string path){var mode=new LaunchMode{id="preview-mode",name="Stream",description="Retrouver mes outils pour préparer un live.",actions=new List<ModeAction>{new ModeAction{kind="discord",label="Discord"},new ModeAction{kind="spotify",label="Spotify"},new ModeAction{kind="url",label="Mon espace Twitch",target="https://dashboard.twitch.tv"}}};store.Value.modes.Add(mode);selected="Mes modes";Refresh();Preview(path+"-modes.png");previewPrefix=path;EditMode(mode);previewPrefix=null;store.Value.modes.Remove(mode);}
